#'
#' @export
american_option_lv <- function(s_0, k, tau, r_d, r_f, sigma, type, s_min, s_max, n_s, n_t, lambda, tolerance) {
    .Call(`_LocalVolatility_american_option_lv`, s_0, k, tau, r_d, r_f, sigma, type, s_min, s_max, n_s, n_t, lambda, tolerance)
}

